const unit = 0.6;
const left = -5.6;
const bottom = -2.2;
let side = 2.5;
function corners(x0, y0, width, height) {
  return [[x0,y0,0], [x0+width,y0,0], [x0+width,y0+height,0], [x0,y0+height,0]];
}
const core = new Polygon({ vertices: corners(left, bottom, side*unit, side*unit), color: BLUE });
core.setFill(BLUE, 0.45);
const upper = new Polygon({ vertices: corners(left, bottom+side*unit, side*unit, 3*unit), color: ORANGE });
upper.setFill(ORANGE, 0.35);
const rightStrip = new Polygon({ vertices: corners(left+side*unit, bottom, 3*unit, side*unit), color: ORANGE });
rightStrip.setFill(ORANGE, 0.35);
const corner = new Polygon({ vertices: corners(left+side*unit, bottom+side*unit, 3*unit, 3*unit), color: GREEN });
corner.setFillOpacity(0);

async function mathLabel(latex, color, position, size) {
  const label = new MathTex({ latex, color, fontSize: size });
  await label.waitForRender();
  label.moveTo(position);
  return label;
}
const coreLabel = await mathLabel('x^2', WHITE, [left+side*unit/2,bottom+side*unit/2,0], 28);
const upperLabel = await mathLabel('3x', WHITE, [left+side*unit/2,bottom+side*unit+1.5*unit,0], 28);
const stripLabel = await mathLabel('3x', WHITE, [left+side*unit+1.5*unit,bottom+side*unit/2,0], 28);
const cornerLabel = await mathLabel('9', GREEN, [left+side*unit+1.5*unit,bottom+side*unit+1.5*unit,0], 32);
const sideX = await mathLabel('x', BLUE, [left+side*unit/2,bottom-0.3,0], 24);
const sideThree = await mathLabel('3', ORANGE, [left+side*unit+1.5*unit,bottom-0.3,0], 24);
