const leftThree = await mathLabel('3', ORANGE, [left-0.3,bottom+side*unit+1.5*unit,0], 24);

const splitFormula = await mathLabel('x^2+6x=x^2+3x+3x', WHITE, [2.8,1.55,0], 27);
await scene.play(new Create(core));
await scene.play(new Write(coreLabel));
await scene.play(new AnimationGroup([new Create(upper), new Create(rightStrip)]));
scene.add(upperLabel, stripLabel, sideX, sideThree, leftX, leftThree);
await scene.play(new Write(splitFormula));
await scene.wait(1);
await scene.play(new Create(corner));

